  // Temperature page
  temperature: {
    title: 'Temperature',
    description: "How temperature changes next-token probabilities and sample diversity.",
    whatIs: 'What is Temperature?',
    whatIsTerm: 'Temperature',
    whatIsDesc: "is a sampling parameter: before softmax turns the logits (raw scores) for the next token into probabilities, every logit is divided by T. It controls how strongly sampling favours the most likely options over less likely ones. T = 1 leaves the model’s distribution unchanged.",
    lowTemp: 'Low Temperature',
    lowTempDesc: "Concentrates probability on the highest logits. This makes sampling less varied, but does not make incorrect information true.",
    highTemp: 'High Temperature',
    highTempDesc: "Flattens the distribution and gives lower-logit tokens more probability. The effect on task quality depends on the model and task.",
    interactiveDistribution: 'Interactive Distribution',
    adjustSlider: 'Adjust the temperature to see its effect',
    adjustDesc: "Compare the calculated distribution with actual draws from five example logits. Changing temperature clears the old sample counts.",
    demo: {
      note: 'Five example tokens with fixed logits [3, 2, 1, 0, −1]. Samples come from exactly the distribution shown here. The exercise measures how often each token is chosen, not the quality of whole answers.',
      tempLabel: 'Temperature T',
      tokens: ['mat', 'blanket', 'lawn', 'staircase', 'couch'],
      legend: 'Purple: calculated probability. Cyan: observed share of the draws. Finite samples fluctuate. At T = 0 the demo uses greedy decoding.',
      sample: 'Sample 100 tokens',
      clear: 'Clear counts',
    },
    howItWorks: 'How it Works Mathematically',
    mathDesc: 'The model generates a score for every possible token. To get probabilities, we use the Softmax function, modified by temperature:',
    whenLow: 'When T → 0',
    low: 'Low',
    whenLowDesc: 'Dividing by a small T amplifies differences between scores. The highest logit dominates exponentially.',
    whenHigh: 'When T → ∞',
    high: 'High',
    whenHighDesc: 'Dividing by a large T compresses all scores toward zero, making them nearly equal after exponentiation.',
    truncationTitle: 'Temperature together with top-p and min-p',
    truncationBody: 'Temperature reshapes the whole distribution. Truncation samplers then remove the unlikely tail before a token is drawn, and the remaining probabilities are renormalized.',
    truncationTopP: 'Top-p (nucleus sampling) keeps the smallest set of most likely tokens whose combined probability reaches p. A flat distribution needs many tokens to reach p; a peaked one needs only a few.',
    truncationMinP: "Min-p keeps every token whose probability is at least p_min times the probability of the most likely token. The cutoff therefore follows the model’s confidence at each step.",
    truncationOrder: "The order matters. If temperature is applied first, a higher T flattens the distribution and lets more tokens into the top-p set. If it is applied last, truncation is decided on the unscaled distribution and temperature only redistributes probability among the surviving tokens. llama.cpp’s default sampler chain ends with temperature, after top-k, top-p and min-p; other libraries order the steps differently. This is why model cards recommend combinations of settings rather than a single temperature.",
    practicalGuidelines: 'Practical Guidelines',
    guidelinesBody: 'Start with guidance for the specific model and mode. Then compare settings on the same tasks and reference answers over multiple runs. Facts need sources and code needs tests; temperature does not replace these checks.',
    guidelinesExample: 'For example, Qwen3 recommends T = 0.6, top-p = 0.95, top-k = 20 and min-p = 0 for thinking mode and warns against greedy decoding. A universal recipe such as "always use T = 0 for math" would not fit this model.',
    sourcesTitle: 'Sources',
    keyTakeaways: 'Key Takeaways',
    takeaway1: "T = 0 commonly selects greedy decoding. Repeated API calls can still differ because other parts of inference may vary.",
    takeaway2: "Temperature changes the distribution, not the model’s stored knowledge.",
    takeaway3: "No universal temperature threshold guarantees truth, creativity or incoherence.",
    takeaway4: "Compare task results and follow model-specific guidance, especially for reasoning modes.",
  },

