    skillType4Title: 'Integration Skills',
    skillType4Desc: 'Instructions for working with specific tools or services—GitHub workflows, Jira ticket creation, Slack notifications.',

    // Skills vs Tools
    vsToolsTitle: 'Skills vs. Tools',
    tools: 'Tools',
