      worldGenesis: "Genesis is a physics simulation platform. Its speed claims depend on a specific simulator, task and hardware; they are not performance guarantees for learned world models.",
      localHardware: "Start with storage arithmetic. A hypothetical 70B model needs at least 35 GB (32.6 GiB) for raw 4-bit weights or 70 GB (65.2 GiB) for 8-bit weights. Quantization metadata, KV cache and runtime buffers come on top. A 24 GB GPU therefore needs partial offload or a smaller model.",
